#define _POSIX_C_SOURCE 200809L
/* core-keeper oracle: the storage owner driving draft queues against the real store.
 * Shares only the public keeper/draft/document/store API with the implementation. Text is
 * generated by a deterministic edit script, so any durable revision can be checked exactly. */
#include "keeper.h"
#include <pthread.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <time.h>
#include <unistd.h>

static int failures;
#define CHECK(c) do { if (!(c)) { fprintf(stderr, "FAIL %s:%d %s\n", __FILE__, __LINE__, #c); failures++; } } while (0)
#define MUST(c) do { if (!(c)) { fprintf(stderr, "FATAL %s:%d %s\n", __FILE__, __LINE__, #c); exit(1); } } while (0)
static char base[3000];
static const char *path(const char *name) { static char p[8][3100]; static int i; i = (i + 1) % 8; snprintf(p[i], sizeof p[i], "%s/%s", base, name); return p[i]; }
enum { CAP = 1 << 18 };

/* Edit script: step j applied to a text of length n. */
typedef struct { uint16_t text[CAP]; size_t length; } model;
static td_edit script(unsigned j, size_t n, uint16_t *unit) {
    *unit = (uint16_t)(0x100 + j % 5000);
    if (j % 5 == 4 && n) { size_t at = (j * 3u) % n; return (td_edit){at, at + 1, NULL, 0}; }
    size_t at = (j * 7u) % (n + 1);
    return (td_edit){at, at, unit, 1};
}
static void apply(model *m, td_edit e) {
    memmove(m->text + e.start + e.length, m->text + e.end, (m->length - e.end) * 2);
    if (e.length) memcpy(m->text + e.start, e.text, e.length * 2);
    m->length = m->length - (e.end - e.start) + e.length;
}
static uint64_t fnv(const uint16_t *p, size_t n) {
    uint64_t h = 1469598103934665603u;
    for (size_t i = 0; i < n; i++) { h ^= p[i]; h *= 1099511628211u; }
    return h ^ n;
}
typedef struct { uint64_t id; } created;
static ts_status make_document(ts_store *s, void *arg) {
    td_text_value v = {NULL, 0, 0, -1, -1}; td_snapshot snap;
    ts_status st = td_save_text(s, (ts_read){0, 0}, &v, &snap);
    ((created *)arg)->id = snap.record.id;
    return st;
}
static uint64_t create(tk_owner *k) { created c; MUST(tk_run(k, make_document, &c) == TS_OK); return c.id; }
static int durable_is(const char *dir, uint64_t id, uint64_t revision, const uint16_t *text, size_t n) {
    ts_store *s; MUST(ts_open(dir, &s) == TS_OK);
    static uint16_t buf[CAP]; td_snapshot snap;
    int ok = td_load(s, id, revision, &snap, buf, CAP) == TS_OK && snap.length == n && !memcmp(buf, text, n * 2);
    ts_close(s);
    return ok;
}

/* Typing on one thread while the keeper saves; periodic flushes name revisions whose text is
 * the text at some local revision at or after the one flushed. */
typedef struct { tk_owner *k; ti_queue *q; uint64_t doc; model m; uint64_t *hashes; unsigned edits, flushes, exact; } typist;
static ts_status load_hash(ts_store *s, void *arg) {
    uint64_t *io = arg; static uint16_t buf[CAP]; td_snapshot snap;
    ts_status st = td_load(s, io[0], io[1], &snap, buf, CAP);
    io[2] = st ? 0 : fnv(buf, snap.length);
    return st;
}
static void *type(void *arg) {
    typist *t = arg;
    t->hashes[0] = fnv(t->m.text, 0);
    for (unsigned j = 0; j < t->edits; j++) {
        uint16_t unit; td_edit e = script(j, t->m.length, &unit); uint64_t local;
        MUST(ti_edit(t->q, &e, 1, 0, 0, -1, -1, &local) == TS_OK && local == j + 1);
        apply(&t->m, e);
        t->hashes[local] = fnv(t->m.text, t->m.length);
        tk_poke(t->k);
        if (j % 400 == 399) {
            ts_read durable;
            MUST(tk_flush(t->k, t->q, local, 0, &durable) == TS_OK && durable.id == t->doc);
            uint64_t io[3] = {durable.id, durable.revision, 0};
            MUST(tk_run(t->k, load_hash, io) == TS_OK);
            int found = 0;
            for (uint64_t l = local; l <= j + 1 && !found; l++) found = t->hashes[l] == io[2];
            CHECK(found);
            t->flushes++; t->exact += found;
        }
    }
    return NULL;
}
static void typing(void) {
    tk_owner *k; MUST(tk_start(path("typing"), &k) == TS_OK);
    static typist t; t.k = k; t.doc = create(k); t.edits = 4000;
    t.hashes = calloc(t.edits + 1, sizeof *t.hashes);
    MUST(tk_attach(k, t.doc, 0, &t.q) == TS_OK);
    pthread_t th; MUST(!pthread_create(&th, NULL, type, &t));
    pthread_join(th, NULL);
    ts_read durable;
    CHECK(tk_flush(k, t.q, t.edits, 0, &durable) == TS_OK);
    CHECK(tk_detach(k, t.q) == TS_OK);
    tk_stats stats; tk_stats_get(k, &stats);
    tk_stop(k);
    CHECK(durable_is(path("typing"), t.doc, 0, t.m.text, t.m.length));
    CHECK(stats.saves >= 1 && stats.saves <= t.edits && stats.failures == 0);
    printf("ok keeper typing: %u edits saved in %llu coalesced saves; %u/%u flushes named exact durable text\n",
           t.edits, (unsigned long long)stats.saves, t.exact, t.flushes);
    free(t.hashes);
}

/* Agent edits through tk_run: disjoint ones merge into the live draft, overlapping ones put
 * the draft in conflict until the owner decides. */
typedef struct { uint64_t id; size_t at, end; uint16_t unit; } agent_edit;
static ts_status agent(ts_store *s, void *arg) {
    agent_edit *a = arg; td_snapshot cur; tx_text *t, *n;
    ts_status st = td_load_text(s, a->id, 0, &cur, &t);
    if (st) return st;
    size_t at = a->at == SIZE_MAX ? tx_length(t) : a->at, end = a->end == SIZE_MAX ? at : a->end;
    if (!(st = tx_edit(t, at, end, &a->unit, 1, &n))) {
        td_text_value v = {n, 0, 0, -1, -1}; td_snapshot r;
        st = td_save_text(s, (ts_read){a->id, cur.record.revision}, &v, &r);
        tx_release(n);
    }
    tx_release(t);
    return st;
}
typedef struct { ti_queue *q; agent_edit a; uint64_t local; } race;
static ts_status edit_then_agent(ts_store *s, void *arg) {
    race *r = arg;
    ts_status st = ti_edit(r->q, &(td_edit){2, 3, (uint16_t[]){'E'}, 1}, 1, 3, 3, -1, -1, &r->local);
    return st ? st : agent(s, &r->a);
}
static ts_status latest_revision(ts_store *s, void *arg) {
    uint64_t *l = arg; ts_record r;
    ts_status st = ts_get(s, l[0], &r, NULL, 0);
    l[1] = r.revision;
    return st == TS_CAPACITY ? TS_OK : st;
}
static void agents(void) {
    tk_owner *k; MUST(tk_start(path("agents"), &k) == TS_OK);
    uint64_t doc = create(k); ti_queue *q;
    MUST(tk_attach(k, doc, 0, &q) == TS_OK);
    uint16_t hello[] = {'h', 'e', 'l', 'l', 'o'}; uint64_t local;
    MUST(ti_edit(q, &(td_edit){0, 0, hello, 5}, 1, 5, 5, -1, -1, &local) == TS_OK);
    tk_poke(k);
    ts_read d; MUST(tk_flush(k, q, local, 0, &d) == TS_OK);
    int fd = tk_notify_fd(k); uint64_t events;
    CHECK(fd >= 0 && read(fd, &events, sizeof events) < 0);    /* own saves do not notify */
    /* Local typing at the start (not yet saved) and an agent append at the end. */
    MUST(ti_edit(q, &(td_edit){0, 0, (uint16_t[]){'>'}, 1}, 1, 1, 1, -1, -1, &local) == TS_OK);
    agent_edit append = {doc, SIZE_MAX, SIZE_MAX, '!'};
    MUST(tk_run(k, agent, &append) == TS_OK);
    tk_poke(k);
    MUST(tk_flush(k, q, local, 0, &d) == TS_OK);
    CHECK(read(fd, &events, sizeof events) == sizeof events && events >= 1);   /* the merge did */
    uint16_t want[] = {'>', 'h', 'e', 'l', 'l', 'o', '!'}, got[16]; td_value v; ti_state st;
    MUST(ti_view(q, got, 16, &v, &st) == TS_OK);
    CHECK(v.length == 7 && !memcmp(got, want, 14) && v.caret == 1 && st.external >= 1);
    CHECK(tk_flush(k, q, st.local, 0, &d) == TS_OK);
    /* Overlap: the user and an agent both rewrite 'e'. Both happen inside one keeper task, so
     * the user's edit is certainly unsaved when the agent commits over it. */
    race r = {q, {doc, 2, 3, '3'}, 0};
    MUST(tk_run(k, edit_then_agent, &r) == TS_OK);
    local = r.local;
    tk_poke(k);
    CHECK(tk_flush(k, q, local, 2000, &d) == TS_CONFLICT);
    CHECK(read(fd, &events, sizeof events) == sizeof events && events >= 1);   /* so did the conflict */
    MUST(ti_view(q, got, 16, &v, &st) == TS_OK);
    CHECK(st.phase == TI_CONFLICT && got[2] == 'E');
    ts_store *peek;
    CHECK(ts_open(path("agents"), &peek) == TS_CONFLICT);   /* the keeper alone owns the store */
    tk_stats stats; tk_stats_get(k, &stats);
    CHECK(stats.conflicts >= 1);
    /* The owner keeps its text over the conflicting (latest durable) revision. */
    uint64_t latest[2] = {doc, 0};
    MUST(tk_run(k, latest_revision, latest) == TS_OK);
    MUST(ti_resolve_keep(q, latest[1]) == TS_OK);
    ti_state now; ti_state_get(q, &now);
    tk_poke(k);
    MUST(tk_flush(k, q, now.local, 0, &d) == TS_OK);
    CHECK(tk_detach(k, q) == TS_OK);
    tk_stop(k);
    uint16_t kept[] = {'>', 'h', 'E', 'l', 'l', 'o', '!'};
    CHECK(durable_is(path("agents"), doc, 0, kept, 7));
    puts("ok keeper agents: disjoint agent edit merged into the live draft; overlap conflicts until the owner keeps its text; both signal the notify fd, own saves do not");
}

/* Storage failure: saves back off instead of spinning, flush reports the failure, and the
 * draft is saved once storage recovers. */
static ts_status quota(ts_store *s, void *arg) { return ts_limit_pages(s, *(uint64_t *)arg); }
static void failing(void) {
    tk_owner *k; MUST(tk_start(path("failing"), &k) == TS_OK);
    uint64_t doc = create(k); ti_queue *q;
    MUST(tk_attach(k, doc, 0, &q) == TS_OK);
    uint64_t one = 1, none = 0, local;
    MUST(tk_run(k, quota, &one) == TS_OK);
    /* Large enough that its manifest and references need new database pages. */
    static uint16_t big[200000];
    for (size_t i = 0; i < 200000; i++) big[i] = (uint16_t)('a' + i % 26);
    MUST(ti_edit(q, &(td_edit){0, 0, big, 200000}, 1, 0, 0, -1, -1, &local) == TS_OK);
    tk_poke(k);
    ts_read d;
    CHECK(tk_flush(k, q, local, 400, &d) == TS_FULL);
    tk_stats a; tk_stats_get(k, &a);
    CHECK(a.failures >= 1 && a.failures <= 6);           /* 50, 100, 200 ms backoff: no spinning */
    /* Pokes (typing) do not bypass backoff: 20 wakes over 100 ms add at most one attempt. */
    for (int i = 0; i < 20; i++) { tk_poke(k); nanosleep(&(struct timespec){0, 5000000L}, NULL); }
    tk_stats b; tk_stats_get(k, &b);
    CHECK(b.failures <= a.failures + 1);
    MUST(tk_run(k, quota, &none) == TS_OK);
    CHECK(tk_flush(k, q, local, 0, &d) == TS_OK && d.revision == 2);
    CHECK(tk_detach(k, q) == TS_OK);
    tk_stop(k);
    CHECK(durable_is(path("failing"), doc, 0, big, 200000));
    printf("ok keeper failure: TS_FULL reported after %llu backed-off attempts; saved once storage recovered\n",
           (unsigned long long)b.failures);
}

/* tk_stop saves pending edits before closing. */
static void drain(void) {
    tk_owner *k; MUST(tk_start(path("drain"), &k) == TS_OK);
    uint64_t doc = create(k); ti_queue *q;
    MUST(tk_attach(k, doc, 0, &q) == TS_OK);
    static model m;
    for (unsigned j = 0; j < 300; j++) {
        uint16_t unit; td_edit e = script(j, m.length, &unit);
        MUST(ti_edit(q, &e, 1, 0, 0, -1, -1, NULL) == TS_OK); apply(&m, e);
    }
    tk_stop(k);                                           /* no poke, no flush */
    CHECK(durable_is(path("drain"), doc, 0, m.text, m.length));
    puts("ok keeper drain: stop saved 300 unpoked edits before closing the store");
}

/* SIGKILL: after any flush returned, the durable text is the text at that local revision or a
 * later one. The edit script lets the parent reconstruct every intermediate text. */
static void killed(void) {
    unsigned cycles = 6, checked = 0;
    for (unsigned c = 0; c < cycles; c++) {
        char name[32]; snprintf(name, sizeof name, "killed-%u", c);
        int report[2]; MUST(pipe(report) == 0);
        pid_t child = fork(); MUST(child >= 0);
        if (!child) {
            close(report[0]);
            tk_owner *k; MUST(tk_start(path(name), &k) == TS_OK);
            uint64_t doc = create(k); ti_queue *q;
            MUST(tk_attach(k, doc, 0, &q) == TS_OK);
            MUST(write(report[1], &doc, sizeof doc) == sizeof doc);
            static model m;
            for (unsigned j = 0;; j++) {
                uint16_t unit; td_edit e = script(j, m.length, &unit); uint64_t local;
                MUST(ti_edit(q, &e, 1, 0, 0, -1, -1, &local) == TS_OK); apply(&m, e);
                tk_poke(k);
                if (j % 97 == 0) {
                    ts_read d; MUST(tk_flush(k, q, local, 0, &d) == TS_OK);
                    MUST(write(report[1], &local, sizeof local) == sizeof local);
                }
            }
        }
        close(report[1]);
        uint64_t doc, flushed = 0, value;
        MUST(read(report[0], &doc, sizeof doc) == sizeof doc);
        nanosleep(&(struct timespec){0, 150000000L + 70000000L * c}, NULL);
        MUST(kill(child, SIGKILL) == 0); int status; MUST(waitpid(child, &status, 0) == child);
        while (read(report[0], &value, sizeof value) == sizeof value) flushed = value;
        close(report[0]);
        ts_store *s; MUST(ts_open(path(name), &s) == TS_OK);
        static uint16_t buf[CAP]; td_snapshot snap;
        MUST(td_load(s, doc, 0, &snap, buf, CAP) == TS_OK);
        ts_close(s);
        uint64_t want = fnv(buf, snap.length);
        static model m; m.length = 0;
        uint64_t match = UINT64_MAX;
        if (fnv(m.text, 0) == want) match = 0;
        for (unsigned j = 0; j < 200000 && match == UINT64_MAX; j++) {
            uint16_t unit; td_edit e = script(j, m.length, &unit); apply(&m, e);
            if (j + 1 >= flushed && fnv(m.text, m.length) == want) match = j + 1;
        }
        CHECK(match != UINT64_MAX && match >= flushed);
        checked += match != UINT64_MAX && match >= flushed;
    }
    printf("ok keeper SIGKILL: %u/%u cycles recovered the text of a local revision at or after the last flush\n", checked, cycles);
}

int main(int argc, char **argv) {
    if (argc != 2 || strlen(argv[1]) >= sizeof base) { fprintf(stderr, "usage: core-keeper <directory>\n"); return 2; }
    strcpy(base, argv[1]); mkdir(base, 0700);
    typing(); agents(); failing(); drain(); killed();
    if (failures) { fprintf(stderr, "core-keeper: %d failures\n", failures); return 1; }
    puts("core-keeper: all checks passed (storage owner semantics, not Android lifecycle or IME evidence)"); return 0;
}
